}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.preview-area {
    margin-top: 2rem;
}

.preview-area h4 {
    margin-bottom: 0.75rem;
    color: #4a5568;
}

.preview-box {
    padding: 1.5rem;
    border-radius: 8px;
    border: 1px solid #e2e8f0;
    transition: all 0.2s;
}

.preview-box.theme-light {
    background: #ffffff;
