}

.preview-box.theme-dark {
    background: #1a202c;
    color: #e2e8f0;
}

.preview-box.theme-system {
    background: #f7fafc;
    color: #2d3748;
}

.preview-box.font-small {
    font-size: 0.85rem;
}

.preview-box.font-medium {
    font-size: 1rem;
}

.preview-box.font-large {
    font-size: 1.15rem;
}

.preview-box.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-title {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.preview-btn {
    margin-top: 0.75rem;
    padding: 0.4rem 1rem;
    border: none;
    border-radius: 4px;
    background: #3182ce;
    color: #fff;
    cursor: pointer;
}

.preview-box.theme-dark .preview-btn {
    background: #63b3ed;
    color: #1a202c;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    padding: 0.75rem 1.25rem;
    border-radius: 6px;
    color: #fff;
    font-weight: 500;
    animation: slideIn 0.3s ease;
    z-index: 1000;
}

.toast.success {
    background: #38a169;
}

.toast.error {
    background: #e53e3e;
}

@keyframes slideIn {
    from { transform: translateY(1rem); opacity: 0; }
    to { transform: translateY(0); opacity: 1; }
}

/* Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1001;
}

.modal {
    background: #fff;
    padding: 1.5rem 2rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
}

.modal h3 {
    margin-top: 0;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
    margin-top: 1.25rem;
}

/* Loading */
.loading {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 3rem;
    color: #718096;
}

