{"file_text": "@page "/settings"
@rendermode InteractiveServer
@using sv_45557d436e8747c6a005963f1d7768fc.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (IsLoading)
        {
            <div class="loading">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">@ToastMessage</div>
        }
    </main>
</div>

@if (ShowRevokeConfirmation)
{
    <div class="modal-overlay" @onclick="CancelRevoke">
        <div class="modal" @onclick:stopPropagation="true">
            <h3>Revoke Session</h3>
            <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
            <div class="modal-actions">
                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
            </div>
        </div>
    </div>
}

@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool IsLoading { get; set; } = true;
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "success";

    // Profile state
    private string ProfileDisplayName { get; set; } = "";
    private string ProfileEmail { get; set; } = "";
    private string ProfileAvatarUrl { get; set; } = "";
    private string ProfileBio { get; set; } = "";
    private UserProfile? _savedProfile;

    // Notifications state
    private bool EmailNotifications { get; set; }
    private bool PushNotifications { get; set; }
    private bool WeeklyDigest { get; set; }
    private List<ChannelMuteState> Channels { get; set; } = new();

    // Security state
    private SecuritySettings? _securitySettings;
    private bool PasswordPanelExpanded { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private bool ShowRevokeConfirmation { get; set; }
    private string? _sessionToRevoke;

    // Appearance state
    private string SelectedTheme { get; set; } = "Light";
    private string SelectedFontSize { get; set; } = "Medium";
    private string SelectedLanguage { get; set; } = "English";
    private bool CompactMode { get; set; }

    private static readonly string[] AvailableLanguages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        ActiveSection = section;
        IsLoading = true;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        switch (ActiveSection)
        {
            case "Profile":
                var profile = await SettingsService.GetProfileAsync();
                _savedProfile = profile;
                ProfileDisplayName = profile.DisplayName;
                ProfileEmail = profile.Email;
                ProfileAvatarUrl = profile.AvatarUrl;
                ProfileBio = profile.Bio;
                break;
            case "Notifications":
                var prefs = await SettingsService.GetNotificationPrefsAsync();
                EmailNotifications = prefs.EmailNotifications;
                PushNotifications = prefs.PushNotifications;
                WeeklyDigest = prefs.WeeklyDigest;
                Channels = prefs.MutedChannels.Select(c => new ChannelMuteState(c, true)).ToList();
                break;
            case "Security":
                _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                PasswordPanelExpanded = false;
                CurrentPassword = "";
                NewPassword = "";
                ConfirmPassword = "";
                break;
            case "Appearance":
                var appearance = await SettingsService.GetAppearanceAsync();
                SelectedTheme = appearance.Theme;
                SelectedFontSize = appearance.FontSize;
                SelectedLanguage = appearance.Language;
                CompactMode = appearance.CompactMode;
                break;
        }
        IsLoading = false;
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(ProfileDisplayName, ProfileEmail, ProfileAvatarUrl, ProfileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ProfileDisplayName = _savedProfile.DisplayName;
            ProfileEmail = _savedProfile.Email;
            ProfileAvatarUrl = _savedProfile.AvatarUrl;
            ProfileBio = _savedProfile.Bio;
        }
    }

    // Notifications actions
    private async Task SaveNotifications()
    {
        var mutedChannels = Channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        PasswordPanelExpanded = false;
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Password updated successfully!", "success");
    }

    private void RequestRevoke(string sessionId)
    {
        _sessionToRevoke = sessionId;
        ShowRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        ShowRevokeConfirmation = false;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.", "success");
        }
        ShowRevokeConfirmation = false;
        _sessionToRevoke = null;
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    private void ShowToast(string message, string type)
    {
        ToastMessage = message;
        ToastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        ToastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    // Render methods
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <div class="section-header">
            <h2>Profile</h2>
            <p class="section-description">Manage your public profile information</p>
        </div>

        <div class="profile-layout">
            <div class="avatar-area">
                <div class="avatar-preview">
                    <img src="@ProfileAvatarUrl" alt="Avatar" />
                </div>
                <span class="avatar-url-label">@ProfileAvatarUrl</span>
            </div>

            <div class="form-fields">
                <div class="form-group">
                    <label for="displayName">Display Name</label>
                    <input id="displayName" type="text" @bind="ProfileDisplayName" />
                </div>
                <div class="form-group">
                    <label for="email">Email</label>
                    <input id="email" type="email" @bind="ProfileEmail" />
                </div>
                <div class="form-group">
                    <label for="bio">Bio</label>
                    <textarea id="bio" rows="4" @bind="ProfileBio"></textarea>
                </div>
            </div>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <div class="section-header">
            <h2>Notifications</h2>
            <p class="section-description">Configure how and when you receive notifications</p>
        </div>

        <div class="toggle-group">
            <label class="toggle-row">
                <span>Email Notifications</span>
                <input type="checkbox" class="toggle-switch" @bind="EmailNotifications" />
            </label>
            <label class="toggle-row">
                <span>Push Notifications</span>
                <input type="checkbox" class="toggle-switch" @bind="PushNotifications" />
            </label>
            <label class="toggle-row">
                <span>Weekly Digest</span>
                <input type="checkbox" class="toggle-switch" @bind="WeeklyDigest" />
            </label>
        </div>

        <h3>Muted Channels</h3>
        <div class="channels-list">
            @foreach (var channel in Channels)
            {
                <label class="channel-item">
                    <input type="checkbox" checked="@channel.IsMuted"
                           @onchange="(e) => channel.IsMuted = (bool)(e.Value ?? false)" />
                    <span>#@channel.Name</span>
                </label>
            }
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <div class="section-header">
            <h2>Security</h2>
            <p class="section-description">Manage your account security and active sessions</p>
        </div>

        <div class="security-card">
            <div class="expandable-header" @onclick="() => PasswordPanelExpanded = !PasswordPanelExpanded">
                <h3>Change Password</h3>
                <span class="expand-icon">@(PasswordPanelExpanded ? "▲" : "▼")</span>
            </div>
            @if (PasswordPanelExpanded)
            {
                <div class="expandable-content">
                    <div class="form-group">
                        <label for="currentPwd">Current Password</label>
                        <input id="currentPwd" type="password" @bind="CurrentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPwd">New Password</label>
                        <input id="newPwd" type="password" @bind="NewPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPwd">Confirm Password</label>
                        <input id="confirmPwd" type="password" @bind="ConfirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    @if (_securitySettings?.LastPasswordChange is not null)
                    {
                        <p class="hint">Last changed: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }
                </div>
            }
        </div>

        <div class="security-card">
            <div class="toggle-row">
                <span>
                    Two-Factor Authentication
                    @if (_securitySettings?.TwoFactorEnabled == true)
                    {
                        <span class="status-badge enabled">Enabled</span>
                    }
                    else
                    {
                        <span class="status-badge disabled">Disabled</span>
                    }
                </span>
                <input type="checkbox" class="toggle-switch" checked="@(_securitySettings?.TwoFactorEnabled ?? false)" disabled />
            </div>
        </div>

        <div class="security-card">
