                {
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@size" checked="@(SelectedFontSize == size)"
                               @onchange="() => SelectedFontSize = size" />
                        @size
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="SelectedLanguage">
                @foreach (var lang in AvailableLanguages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="toggle-row">
            <span>Compact Mode</span>
            <input type="checkbox" class="toggle-switch" @bind="CompactMode" />
        </div>

        <div class="preview-area">
            <h4>Live Preview</h4>
            <div class="preview-box @GetPreviewClasses()">
                <p class="preview-title">Sample Content</p>
                <p>This is how your content will appear with the selected settings.</p>
                <button class="preview-btn">Sample Button</button>
            </div>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    };

    private string GetPreviewClasses()
    {
        var classes = $"theme-{SelectedTheme.ToLower()} font-{SelectedFontSize.ToLower()}";
        if (CompactMode) classes += " compact";
        return classes;
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    private class ChannelMuteState
    {
        public string Name { get; set; }
        public bool IsMuted { get; set; }
        public ChannelMuteState(string name, bool isMuted) { Name = name; IsMuted = isMuted; }
    }
}
